-- Sean's Templates notes, 2026-11-11. Safe to run twice (version guards).
update public.knowledge_records set version=3, updated_by='logan', updated_at=now(),
  change_summary='v3: asset packs (Sean, 2026-11-11): every new picture is made in all five shapes at once.',
  body = jsonb_set(body, '{asset_packs}', $j$"Sean, 2026-11-11: \"we shouldn't just be fitting round circles into a square hole. Let's design it so it's native to that size... when we create assets, we should know automatically we need to create these... so that way, 2 weeks later, when we need to make a banner using a certain dimension, we're not trying to recreate it in a new session.\" Every new picture (a scene, a city, a show's art) is drawn as a pack in all five shapes at once: 1:1, 4:5, 9:16, 16:9 and the 21:9 strip, each drawn for its shape (never cropped from another), saved together at vegan-media/media/<topic>/<name>/<shape>.jpg and listed in the asset library. First pack: the podcast skyline (public/brand-kit/podcast/skyline-16x9, -21x9, -9x16; 4:5 and 1:1 after the credit top-up)."$j$::jsonb)
where slug='canon-ve-brand-kit-imagery' and status='active' and version=2;
update public.knowledge_records set version=4, updated_by='logan', updated_at=now(),
  change_summary='v4 (2026-11-11, Sean flagged it): EXPLORE optically spaced in the portrait logo; the landscape O notch fixed; the logo lives in the color, never a white chip.',
  body = jsonb_set(jsonb_set(body, '{fixes_2026_11_11}', $j$"Sean: \"is that logo off? It looks like explore is not evenly spaced. Like... the E on the left extends more.\" Measured: VEGANS and EXPLORE were the same width, but the V tapers and the S is round while EXPLORE starts and ends on flat E's, so it read wider. Fix: EXPLORE's letters moved 2.5% of the line's width closer together each side (letter shapes untouched) in logo-ve-portrait-v2.svg, -inverted, -white and their 2000 px PNGs. Also: the landscape v1 O had a notch (one control point 58.546875 where its mirror says 85.078125), fixed in logo-ve-landscape-v1.svg, -inverted, -white. Originals kept at public/brand-kit/logo-before/."$j$::jsonb), '{placement}', $j$"The logo lives in the color, like the carousel end card: all-white on dark green and dark blocks, full color on white; never a white chip dropped on a picture (Sean: \"It looks like it was just kind of slapped on\"). Ads sign off with the logo in a white bar at the bottom. A one-color ink version (logo-ve-portrait-v2-ink) is proposed for orange, pink, peach and the greens, waiting on Sean."$j$::jsonb)
where slug='canon-ve-logo' and status='active' and version=3;
